"use client";
import { useEffect, useState } from "react";

import { cn } from "@/lib/utils";

import type { FabProps, FabIntent, FabPosition, FabSize, FabPlacement } from "./fab.types";

/* Sem token de shadow/elevação no design system ainda (pendência #2 do audit doc) —
   literal oklch ad-hoc, mesmo padrão já usado em Select/Autocomplete/Command/DropdownMenu. */
const SIZE_BTN: Record<FabSize, string> = {
  sm: "w-10 h-10 text-body-callout shadow-[0_4px_16px_-4px_oklch(0%_0_0/0.4)]",
  md: "w-14 h-14 text-body-paragraph shadow-[0_6px_24px_-6px_oklch(0%_0_0/0.4)]",
  lg: "w-16 h-16 text-body-title shadow-[0_8px_28px_-6px_oklch(0%_0_0/0.4)]",
};
const SIZE_ACTION: Record<FabSize, string> = {
  sm: "w-8 h-8 text-body-caption",
  md: "w-10 h-10 text-body-callout",
  lg: "w-12 h-12 text-body-paragraph",
};

const INTENT_CLS: Record<FabIntent, string> = {
  primary: "bg-patina text-patina-fg hover:brightness-110",
  secondary: "bg-kinpaku text-kinpaku-fg hover:brightness-110",
  success: "bg-success text-success-fg hover:brightness-110",
  warning: "bg-warning text-warning-fg hover:brightness-110",
  danger: "bg-danger text-danger-fg hover:brightness-110",
  neutral: "bg-raised text-foreground hover:bg-graphite border border-rule",
};

// absorvido do QuickActions: cor por ação individual (default fica com o visual raised/
// border original do Fab, só entra numa cor de intent quando pedido explicitamente)
const ACTION_INTENT_CLS: Record<FabIntent, string> = {
  primary: "bg-patina text-patina-fg hover:bg-patina-hover",
  secondary: "bg-kinpaku text-kinpaku-fg hover:brightness-110",
  success: "bg-success text-success-fg hover:bg-success-hover",
  warning: "bg-warning text-warning-fg hover:bg-warning-hover",
  danger: "bg-danger text-danger-fg hover:bg-danger-hover",
  neutral: "bg-raised border border-rule text-foreground hover:bg-graphite",
};

const POSITION_CLS: Record<FabPosition, string> = {
  "bottom-right": "fixed bottom-(--spacing-xl) right-(--spacing-xl)",
  "bottom-left": "fixed bottom-(--spacing-xl) left-(--spacing-xl)",
  "top-right": "fixed top-(--spacing-xl) right-(--spacing-xl)",
  "top-left": "fixed top-(--spacing-xl) left-(--spacing-xl)",
  inline: "relative",
};

// mapeia placement -> direção flex de expansão (absorvido do QuickActions, que suportava
// os 4 lados; o Fab original só inferia cima/baixo a partir do canto fixo)
const PLACEMENT_DIR: Record<FabPlacement, string> = {
  top: "flex-col-reverse",
  bottom: "flex-col",
  left: "flex-row-reverse",
  right: "flex-row",
};

const CloseIcon = () => (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" aria-hidden="true" className="w-5 h-5">
    <path d="M18 6L6 18M6 6l12 12" strokeLinecap="round" />
  </svg>
);

/**
 * Botões circulares/tamanho fora da escala do `<Button>` CN (`rounded-full`, `lg` chega a 64px)
 * são específicos deste componente (floating action button + speed-dial) — não reusam `<Button>`
 * pelo mesmo motivo que o chevron do SplitButton não reusa: forma e escala bespoke, não um botão
 * retangular padrão.
 */
export function Fab({
  icon,
  actions = [],
  position = "bottom-right",
  placement,
  intent = "primary",
  size = "md",
  tooltip,
  onClick,
  className,
  style,
}: FabProps) {
  const [open, setOpen] = useState(false);
  const hasActions = actions.length > 0;

  useEffect(() => {
    if (!hasActions || !open) return;
    const handler = (e: KeyboardEvent) => {
      if (e.key === "Escape") setOpen(false);
    };
    document.addEventListener("keydown", handler);
    return () => document.removeEventListener("keydown", handler);
  }, [hasActions, open]);

  // `placement` explícito (absorvido do QuickActions, 4 direções) vence; sem ele, infere
  // cima/baixo a partir do canto fixo (comportamento original do Fab)
  const isBottom = position === "bottom-right" || position === "bottom-left";
  const actionsDir = placement ? PLACEMENT_DIR[placement] : isBottom ? "flex-col-reverse" : "flex-col";

  const mainLabel = tooltip ?? (hasActions ? (open ? "Fechar" : "Abrir menu") : "Ação");

  return (
    <div
      style={style}
      className={cn("z-[900] flex items-center", actionsDir, "gap-(--spacing-md)", POSITION_CLS[position], className)}
    >
      {/* Speed-dial actions */}
      {hasActions && open && (
        <div className={cn("flex", actionsDir, "gap-(--spacing-sm)")} role="group" aria-label="Ações rápidas">
          {actions.map((action, i) => (
            <div key={i} className="flex items-center gap-(--spacing-sm) group">
              {/* group-focus-within (absorvido do QuickActions): sem isso o rótulo só aparecia
                  no hover do mouse, deixando quem navega por teclado sem o nome da ação visível */}
              <span className="text-body-caption text-foreground bg-raised border border-rule rounded-(--radius-sm) px-(--spacing-sm) py-(--spacing-3xs) whitespace-nowrap opacity-0 group-hover:opacity-100 group-focus-within:opacity-100 transition-opacity pointer-events-none select-none">
                {action.label}
              </span>
              <button
                type="button"
                aria-label={action.label}
                disabled={action.disabled}
                onClick={() => {
                  action.onClick();
                  setOpen(false);
                }}
                className={cn(
                  "flex items-center justify-center rounded-full transition-[background,box-shadow] duration-[100ms]",
                  "shadow-[0_4px_16px_-4px_oklch(0%_0_0/0.3)]",
                  ACTION_INTENT_CLS[action.intent ?? "neutral"],
                  SIZE_ACTION[size],
                  action.disabled && "opacity-40 pointer-events-none"
                )}
              >
                {action.icon}
              </button>
            </div>
          ))}
        </div>
      )}

      {/* Main button */}
      <button
        type="button"
        aria-label={mainLabel}
        aria-haspopup={hasActions ? "true" : undefined}
        aria-expanded={hasActions ? open : undefined}
        title={tooltip}
        onClick={() => {
          if (hasActions) setOpen((v) => !v);
          else onClick?.();
        }}
        className={cn(
          "flex items-center justify-center rounded-full transition-[filter,transform] duration-[120ms] active:scale-95 select-none",
          INTENT_CLS[intent],
          SIZE_BTN[size]
        )}
      >
        {hasActions && open ? <CloseIcon /> : icon}
      </button>
    </div>
  );
}

import type React from "react";

export type FabIntent = "primary" | "secondary" | "success" | "warning" | "danger" | "neutral";
export type FabSize = "sm" | "md" | "lg";
// "inline" (absorvido do QuickActions): renderiza no fluxo normal do documento em vez de
// fixed num canto da tela — mesmo botão circular + speed-dial, sem tirar o layout do controle
// do consumidor. `placement` controla a direção de expansão nesse modo.
export type FabPosition = "bottom-right" | "bottom-left" | "top-right" | "top-left" | "inline";
export type FabPlacement = "top" | "bottom" | "left" | "right";

export interface FabAction {
  icon: React.ReactNode;
  label: string;
  onClick: () => void;
  disabled?: boolean;
  /** Cor da ação individual (absorvido do QuickActions) — default 'neutral' (raised/border, visual original do Fab). */
  intent?: FabIntent;
}

export interface FabProps {
  icon: React.ReactNode;
  actions?: FabAction[];
  position?: FabPosition;
  /** Direção de expansão das ações. Se omitido, é inferido de `position` (canto de baixo expande pra cima, canto de cima expande pra baixo); obrigatório fazer sentido só quando `position="inline"`. */
  placement?: FabPlacement;
  intent?: FabIntent;
  size?: FabSize;
  /** Nome acessível do botão principal. Se omitido, cai num fallback genérico ("Ação"/"Abrir menu") — recomendado sempre informar. */
  tooltip?: string;
  onClick?: () => void;
  className?: string;
  style?: React.CSSProperties;
}
